mapper.select:
SELECT -- t_user_coupon 表字段（与实体一致） uc.id, uc.user_openid, uc.coupon_id, uc.get_time, uc.use_time, uc.order_no, uc.status, uc.expire_time, -- t_coupon 表字段（优惠券详情） c.coupon_name, c.discount_value, c.min_amount, c.coupon_type, c.start_time, c.end_time, c.description, c.apply_dining_type, c.apply_dish_ids, c.apply_shop_ids FROM t_user_coupon uc -- 用户优惠券表（左表） LEFT JOIN t_coupon c -- 左连接优惠券表 ON uc.coupon_id = c.id -- 关联条件：用户优惠券表的 coupon_id = 优惠券表主键 id
AND uc.user_openid = #{user_openid}
AND uc.status = #{status}
AND (uc.expire_time IS NULL OR uc.expire_time > #{now}) AND c.id IS NOT NULL AND (c.end_time IS NULL OR c.end_time >= #{now})
ORDER BY uc.get_time DESC

select uc.id, uc.user_openid, uc.coupon_id, uc.get_time, uc.use_time, uc.order_no, uc.status, uc.expire_time, c.coupon_name, c.discount_value, c.min_amount, c.coupon_type, c.start_time, c.end_time, c.description, c.apply_dining_type, c.apply_dish_ids, c.apply_shop_ids FROM t_user_coupon uc LEFT JOIN t_coupon c ON uc.coupon_id = c.id
AND uc.id = #{couponId}
AND uc.user_openid = #{user_openid}
AND uc.status = 0
ORDER BY uc.get_time DESC LIMIT 1

SELECT COUNT(1) FROM t_user_coupon uc LEFT JOIN t_coupon c ON uc.coupon_id = c.id
AND uc.user_openid = #{user_openid}
AND uc.status = #{status}
AND (uc.expire_time IS NULL OR uc.expire_time > #{now}) AND c.id IS NOT NULL AND (c.end_time IS NULL OR c.end_time >= #{now})

SELECT uc.id, uc.user_openid, uc.coupon_id, uc.get_time, uc.use_time, uc.order_no, uc.status, uc.expire_time, c.coupon_name, c.discount_value, c.min_amount, c.coupon_type, c.start_time, c.end_time, c.description, c.apply_dining_type, c.apply_dish_ids, c.apply_shop_ids FROM t_user_coupon uc LEFT JOIN t_coupon c ON uc.coupon_id = c.id
AND uc.user_openid = #{user_openid}
AND uc.status = #{status}
AND (uc.expire_time IS NULL OR uc.expire_time > #{now}) AND c.id IS NOT NULL AND (c.end_time IS NULL OR c.end_time >= #{now})
ORDER BY uc.get_time DESC LIMIT #{limit} OFFSET #{offset}
